Consider this Python code:

class Logger:
    def __init__(self):
        self.entries = []
    def log(self, msg):
        self.entries.append(msg)

class Service:
    def __init__(self, logger=None):
        self.logger = logger if logger else Logger()
    def run(self):
        self.logger.log('run')

